const express = require('express');
const session = require('express-session');
const crypto = require('crypto');
const { ScalekitClient } = require('@scalekit-sdk/node');

const app = express();
const port = 3001;

// Initialize Scalekit Client with dummy credentials if env vars are not provided
const scalekitClient = new ScalekitClient(
  process.env.SCALEKIT_ENV_URL || 'https://dummy.scalekit.com',
  process.env.SCALEKIT_CLIENT_ID || 'dummy_client_id',
  process.env.SCALEKIT_CLIENT_SECRET || 'dummy_client_secret'
);

app.use(session({
  secret: 'my-secret-key',
  resave: false,
  saveUninitialized: true,
  cookie: { secure: false } // Set to true if using HTTPS
}));

app.get('/login', (req, res) => {
  const organizationId = req.query.organization_id;

  if (!organizationId) {
    return res.status(400).send('Missing organization_id query parameter');
  }

  // Generate a random state string
  const state = crypto.randomBytes(16).toString('hex');

  // Store the state in the session
  req.session.state = state;

  const redirectUri = 'http://localhost:3001/callback';

  // Generate the authorization URL
  const authUrl = scalekitClient.getAuthorizationUrl(redirectUri, {
    state: state,
    organizationId: organizationId
  });

  // Redirect the user to the generated URL
  res.redirect(authUrl);
});

// Callback route placeholder
app.get('/callback', (req, res) => {
  res.send('Callback route');
});

app.listen(port, () => {
  console.log(`Server is running on port ${port}`);
});

